/**
 * Hand-maintained type surface for the vendored bunqueue client bundle
 * (`bunqueue-client.js`, generated by scripts/vendor-bunqueue.ts).
 *
 * Deliberately self-contained — it must NOT reference the `bunqueue` package, so
 * that consumers (who never install bunqueue, since it's bundled) still type-check.
 * Only the narrow surface `queue.ts` consumes is declared; keep it in sync with
 * bunqueue's client API when bumping the devDependency.
 */

export interface Job<T = unknown> {
  readonly id: string;
  readonly name: string;
  readonly data: T;
  /** 0-based on the first run. */
  readonly attemptsMade: number;
  /** Epoch ms when the job was enqueued. */
  readonly timestamp: number;
}

export interface JobOptions {
  priority?: number;
  delay?: number;
  attempts?: number;
  jobId?: string;
  [key: string]: unknown;
}

export interface QueueOptions {
  embedded?: boolean;
  dataPath?: string;
  defaultJobOptions?: JobOptions;
  [key: string]: unknown;
}

export interface WorkerOptions {
  embedded?: boolean;
  dataPath?: string;
  concurrency?: number;
  [key: string]: unknown;
}

export class Queue<T = unknown> {
  constructor(name: string, opts?: QueueOptions);
  readonly name: string;
  add(name: string, data: T, opts?: JobOptions): Promise<Job<T>>;
  addBulk(jobs: Array<{ name: string; data: T; opts?: JobOptions }>): Promise<Array<Job<T>>>;
  close(): void;
}

interface WorkerEventMap<T, R> {
  active: (job: Job<T>) => void;
  completed: (job: Job<T>, result: R) => void;
  failed: (job: Job<T>, error: Error) => void;
  error: (error: Error) => void;
}

export class Worker<T = unknown, R = unknown> {
  constructor(name: string, processor: (job: Job<T>) => R | Promise<R>, opts?: WorkerOptions);
  on<E extends keyof WorkerEventMap<T, R>>(event: E, listener: WorkerEventMap<T, R>[E]): this;
  close(): Promise<void>;
}

export function shutdownManager(): void;
